package com.ebuddy.domain; import java.io.Serializable; import java.util.UUID; public class ReceiptKey implements Serializable { public UUID messageId; public UUID recipientUserId; public ReceiptKey(){} public boolean equals(Object o){return o instanceof ReceiptKey x&&java.util.Objects.equals(messageId,x.messageId)&&java.util.Objects.equals(recipientUserId,x.recipientUserId);} public int hashCode(){return java.util.Objects.hash(messageId,recipientUserId);} }
